					<div class="text-tab-content"  id="imTextObject_3_56_tab0" style="">
						<div class="text-inner">
							<div><span class="cf1">26.03.2024</span></div><div><br></div><div><div><span class="fs10 cf1">PIW-Z.511.2.19.2024</span></div></div><div><br></div><div><span class="cf1"><span class="fs10"><b>HARMONOGRAM ODBIORU PRÓB</b></span></span></div><div><div><br></div><div style="text-align: justify;"><span class="fs10 cf1"><span style="line-height: 23px;">W </span><span style="line-height: 23px;">związku ze zbliżającą się przerwą świąteczną oraz blokadą dróg związaną </span><span style="line-height: 23px;">z akcją </span><span style="line-height: 23px;">protestacyjną rolników Powiatowy Lekarz Weterynarii w Białymstoku </span><span style="line-height: 23px;">przesyła </span><span style="line-height: 23px;">harmonogram </span><span style="line-height: 23px;">odbioru </span><span style="line-height: 23px;">prób z chłodni zlokalizowanych na terenie powiatu </span><span style="line-height: 23px;">białostockiego </span><span style="line-height: 23px;">w dn. 01-05.04.2024 r:</span></span></div><div style="text-align: justify;"><br></div><div> &nbsp;</div><div><span class="fs10 cf1"><span style="line-height: 23px;">1 </span><span style="line-height: 23px;">kwietnia </span><span style="line-height: 23px;">2024 r. poniedziałek - dzień wolny, brak odbioru prób;</span></span></div><div> &nbsp;</div><div><span class="fs10 cf1"><span style="line-height: 23px;">3 </span><span style="line-height: 23px;">kwietnia </span><span style="line-height: 23px;">2024 r. środa - odbiór </span><span style="line-height: 23px;">prób;</span></span></div><div> &nbsp;</div><div><span class="fs10 cf1"><span style="line-height: 23px;">4 kwietnia </span><span style="line-height: 23px;">2024 r. czwartek - protesty rolników, brak odbioru prób;</span></span></div><div> &nbsp;</div><div><span class="cf1"><span class="fs12"><a href="files/harmonogram-odbioru-prob_0001.pdf" target="_blank" class="imCssLink"><br></a></span></span></div><div><a href="files/harmonogram-odbioru-prob_0001.pdf" target="_blank" class="imCssLink"><b><span class="cf1">DO POBRANIA: </span><span class="cf1"><span class="fs10">harmonogram odbioru.pdf</span></span></b></a></div><div></div></div><blockquote><div style="text-align: left;"><span class="fs10 cf1"><a href="files/odstrza--sanitarny-27.11.2023.pdf" target="_blank" class="imCssLink"><br></a></span></div><div style="text-align: left;"><br></div></blockquote><div class="cf1"><div style="text-align: -webkit-auto;"><br></div></div>
